# -*- coding: utf-8 -*-
from taf.playwright.core.exceptions import (
    DownloadNotFound,
    PageActionError,
    PlaywrightDependencyMissing,
    PlaywrightTafError,
    SessionNotFound,
    UnsupportedBrowser,
)


class PlaywrightSbtsError(PlaywrightTafError):
    """Base exception for the Playwright SBTS library."""


class SbtsFeatureNotMigrated(PlaywrightSbtsError):
    """Raised when a Selenium SBTS domain has not been migrated yet."""


__all__ = [
    "DownloadNotFound",
    "PageActionError",
    "PlaywrightDependencyMissing",
    "PlaywrightSbtsError",
    "SbtsFeatureNotMigrated",
    "SessionNotFound",
    "UnsupportedBrowser",
]
